#!/bin/sh
# Generated by `re-check lab --write` from book.toml, the chapters' steps and examples/stack.toml. Don't edit by hand.
# Starts this book's lab on your own machine: a workspace with the book's files, and a k3s cluster in Docker through k3d.
set -eu
book_dir=$(cd "$(dirname "$0")/.." && pwd)
slug=k3s-sampler
stack=k3s
lab_home="${RE_LAB_HOME:-$HOME/.rolling-edition/$slug}"
work="$lab_home/work"
bin="$lab_home/bin"

say() { printf '%s\n' "$*"; }
fail() { printf '%s\n' "$*" >&2; exit 1; }

fresh_workspace() {
  case "$work" in */work) ;; *) fail "The workspace must be a folder named work, not $work." ;; esac
  rm -rf "$work"
  mkdir -p "$work" "$bin"
  cp -R "$book_dir/examples/." "$work/"
  rm -f "$work"/*.sh
  find "$work" -name '*.out' -exec rm -f {} +
}
write_env() {
  {
    printf 'export PATH="%s:$PATH"\n' "$bin"
    [ -f "$lab_home/kubeconfig" ] && printf 'export KUBECONFIG="%s"\n' "$lab_home/kubeconfig"
    printf 'cd "%s"\n' "$work"
  } > "$lab_home/env.sh"
}

platform() {
  case "$(uname -s)-$(uname -m)" in
    Linux-x86_64) echo linux-amd64 ;;
    Linux-aarch64|Linux-arm64) echo linux-arm64 ;;
    Darwin-arm64) echo darwin-arm64 ;;
    *) fail "This lab runs on Linux, on x86-64 or Arm, and on macOS on Apple silicon, not on $(uname -s) $(uname -m)." ;;
  esac
}
tool_file() {
  case "$1-$2" in
    k3d-darwin-arm64) echo https://github.com/k3d-io/k3d/releases/download/v5.7.5/k3d-darwin-arm64 2e877c0c33e0fbc497faf3d1b14f22067aa9905c3777faa0abffba392a32ec27 ;;
    k3d-linux-amd64) echo https://github.com/k3d-io/k3d/releases/download/v5.7.5/k3d-linux-amd64 5d3f22817d9e163ab6ed43572189dd49fe724d7a6948075b570067747eca8d3f ;;
    k3d-linux-arm64) echo https://github.com/k3d-io/k3d/releases/download/v5.7.5/k3d-linux-arm64 ac12fcf8e35481769e173c96d3fa70dc581826482d927b94a560a3375df2621e ;;
    kubectl-darwin-arm64) echo https://dl.k8s.io/release/v1.31.4/bin/darwin/arm64/kubectl a756bb911298a85af35c0111c371728a26c532d504fe8b534eb684501fcaf996 ;;
    kubectl-linux-amd64) echo https://dl.k8s.io/release/v1.31.4/bin/linux/amd64/kubectl 298e19e9c6c17199011404278f0ff8168a7eca4217edad9097af577023a5620f ;;
    kubectl-linux-arm64) echo https://dl.k8s.io/release/v1.31.4/bin/linux/arm64/kubectl b97e93c20e3be4b8c8fa1235a41b4d77d4f2022ed3d899230dbbbbd43d26f872 ;;
    helm-darwin-arm64) echo https://get.helm.sh/helm-v3.16.4-darwin-arm64.tar.gz e2442d8f05d53d84c39b869bc5fe5affad247ee2f4c706a040919c146edb1f94 ;;
    helm-linux-amd64) echo https://get.helm.sh/helm-v3.16.4-linux-amd64.tar.gz fc307327959aa38ed8f9f7e66d45492bb022a66c3e5da6063958254b9767d179 ;;
    helm-linux-arm64) echo https://get.helm.sh/helm-v3.16.4-linux-arm64.tar.gz d3f8f15b3d9ec8c8678fbf3280c3e5902efabe5912e2f9fcf29107efbc8ead69 ;;
    *) fail "There's no pinned $1 for $2." ;;
  esac
}
sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d ' ' -f 1
  else shasum -a 256 "$1" | cut -d ' ' -f 1; fi
}
fetch_tool() {
  set -- "$1" $(tool_file "$1" "$(platform)")
  [ -x "$bin/$1" ] && [ "$(cat "$bin/.$1.sha256" 2>/dev/null)" = "$3" ] && return 0
  say "Fetching $1 from $2"
  curl -fsSL "$2" -o "$bin/.$1.part" || fail "Couldn't fetch $2."
  [ "$(sha256_of "$bin/.$1.part")" = "$3" ] || { rm -f "$bin/.$1.part"; fail "$2 isn't the file the book pins: its SHA-256 differs."; }
  case "$2" in
    *.tar.gz) tar -xzf "$bin/.$1.part" -C "$bin" --strip-components 1 "$(platform)/$1" && rm -f "$bin/.$1.part" ;;
    *) mv "$bin/.$1.part" "$bin/$1" ;;
  esac
  chmod +x "$bin/$1"
  printf '%s\n' "$3" > "$bin/.$1.sha256"
}

cluster=re-k3s-sampler
k3s_version=v1.31.4+k3s1
start_cluster() {
  command -v docker >/dev/null 2>&1 || fail "k3d runs the cluster in Docker: install Docker, or Podman with its Docker socket, then run this again."
  docker info >/dev/null 2>&1 || fail "Docker isn't running: start it, then run this again."
  "$bin/k3d" cluster delete "$cluster" >/dev/null 2>&1 || true
  say "Starting the book's cluster, k3s $k3s_version, in Docker"
  "$bin/k3d" cluster create "$cluster" --image docker.io/rancher/k3s:v1.31.4-k3s1@sha256:627fc392e5e7992fb8aa738fb04bc0c9ae9a068999cb4cfbea5858661cd79d04 --no-lb --wait --timeout 300s \
    --k3s-arg '--disable=traefik@server:0' --k3s-arg '--disable=servicelb@server:0' \
    --kubeconfig-update-default=false --kubeconfig-switch-context=false >/dev/null
  "$bin/k3d" kubeconfig get "$cluster" > "$lab_home/kubeconfig"
}

mkdir -p "$lab_home" "$bin"
fresh_workspace
fetch_tool k3d
fetch_tool kubectl
fetch_tool helm
start_cluster
write_env
say "Ready. The workspace is $work."
say "In your terminal: . $lab_home/env.sh"
say "Then start any chapter fresh with lab/chapter.sh CHAPTER_ID, and check your work with lab/check.sh."
